descriptor.templateCss:
.tripguard-control,.tg-control{font-family:"OpenAI Sans", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif}
.tg-control{
  height:100%;box-sizing:border-box;padding:16px;background:#fff;
  border:1px solid #e5e7eb;border-radius:14px;overflow:auto;color:#111827;
  box-shadow:0 1px 3px rgba(15,23,42,.05)
}
.tg-control-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:14px}
.tg-control-title{font-size:18px;line-height:1.25;font-weight:650;letter-spacing:-.01em;color:#0f172a}
.tg-control-sub{margin-top:3px;font-size:12px;line-height:1.4;color:#64748b}
.tg-status{max-width:46%;padding:6px 10px;border-radius:999px;background:#eff6ff;color:#1d4ed8;font-size:11px;font-weight:650;text-align:center;border:1px solid #dbeafe}
.tg-status.sending{background:#fffbeb;color:#92400e;border-color:#fde68a}
.tg-status.success{background:#ecfdf5;color:#047857;border-color:#a7f3d0}
.tg-status.error{background:#fef2f2;color:#b42318;border-color:#fecaca}
.tg-primary-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.tg-btn{
  min-height:42px;border-radius:10px;padding:9px 12px;font-family:inherit;
  font-size:12.5px;font-weight:600;cursor:pointer;transition:background .15s ease,border-color .15s ease,transform .05s ease,box-shadow .15s ease
}
.tg-btn:active{transform:translateY(1px)}
.tg-btn:disabled,.tg-period button:disabled{opacity:.45;cursor:not-allowed}
.tg-btn.primary{border:1px solid #2563eb;background:#2563eb;color:#fff;box-shadow:0 1px 2px rgba(37,99,235,.18)}
.tg-btn.primary:hover{background:#1d4ed8;border-color:#1d4ed8}
.tg-btn.secondary{border:1px solid #dbeafe;background:#eff6ff;color:#1e40af}
.tg-btn.secondary:hover{background:#dbeafe}
.tg-btn.danger{border:1px solid #dc2626;background:#dc2626;color:#fff;box-shadow:0 1px 2px rgba(220,38,38,.18)}
.tg-btn.danger:hover{background:#b91c1c;border-color:#b91c1c}
.tg-sos-remote{width:100%;margin-top:8px}
.tg-advanced{margin-top:12px;border-top:1px solid #eceff3;padding-top:10px}
.tg-advanced summary{cursor:pointer;color:#475569;font-size:12px;font-weight:600;user-select:none}
.tg-advanced-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px;margin-top:10px}
.tg-btn.ghost{border:1px solid #e2e8f0;background:#f8fafc;color:#334155}
.tg-btn.ghost:hover{background:#f1f5f9}
.tg-period{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:10px;padding-top:10px;border-top:1px solid #f0f2f5;font-size:12px;color:#64748b}
.tg-period-actions{display:flex;gap:6px}
.tg-period button{border:1px solid #cbd5e1;background:#fff;color:#334155;border-radius:8px;padding:6px 10px;font:600 11px "OpenAI Sans", ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;cursor:pointer}
.tg-period button:hover{background:#f8fafc}
@media(max-width:650px){
  .tg-control{padding:12px}
  .tg-control-head{flex-direction:column}
  .tg-status{max-width:100%}
  .tg-primary-grid,.tg-advanced-grid{grid-template-columns:1fr}
  .tg-btn{min-height:44px}
}

.tg-offline-note{margin-top:10px;padding:8px 10px;border-radius:9px;background:#fef3f2;border:1px solid #fecdca;color:#b42318;font-size:11.5px;font-weight:600}

descriptor.controllerScript:
var tgControlTimer;

function tgCtrlLatestValue(name) {
  var rows = self.ctx.data || [];
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    if (!row.dataKey || row.dataKey.name !== name || !row.data || !row.data.length) {
      continue;
    }
    var newest = row.data[0];
    for (var j = 1; j < row.data.length; j++) {
      if (row.data[j][0] > newest[0]) { newest = row.data[j]; }
    }
    return newest[1];
  }
  return null;
}

function tgCtrlBool(value) {
  return value === true || value === 1 || value === '1' || value === 'true';
}

function tgCtrlAgeText(lastActivity) {
  if (!Number.isFinite(lastActivity) || lastActivity <= 0) return 'chưa có hoạt động';
  var sec = Math.max(0, Math.floor((Date.now() - lastActivity) / 1000));
  if (sec < 5) return 'vừa cập nhật';
  if (sec < 60) return sec + ' giây trước';
  var min = Math.floor(sec / 60);
  if (min < 60) return min + ' phút trước';
  return Math.floor(min / 60) + ' giờ trước';
}

function tgUpdateDeviceOnline() {
  var scope = self.ctx.$scope;
  var active = tgCtrlBool(tgCtrlLatestValue('active'));
  var lastActivity = Number(tgCtrlLatestValue('lastActivityTime'));
  var freshness = Math.max(10000, Number(self.ctx.settings.onlineFreshnessMs || 30000));
  var age = Number.isFinite(lastActivity) && lastActivity > 0 ? (Date.now() - lastActivity) : null;
  var online = active && (age === null || age <= freshness);
  scope.deviceOnline = online;

  if (!scope.busy) {
    scope.status = online ? ('Online · ' + tgCtrlAgeText(lastActivity)) : ('Offline · ' + tgCtrlAgeText(lastActivity));
    scope.statusClass = online ? 'success' : 'error';
  }
  if (scope.$evalAsync) { scope.$evalAsync(); }
}

self.onInit = function() {
  var scope = self.ctx.$scope;
  scope.busy = false;
  scope.deviceOnline = false;
  scope.status = 'Đang kiểm tra thiết bị...';
  scope.statusClass = 'sending';

  function updateStatus(text, cssClass) {
    scope.status = text;
    scope.statusClass = cssClass;
    if (scope.$evalAsync) { scope.$evalAsync(); }
  }

  scope.sendTripGuardCommand = function(method, params, confirmation) {
    tgUpdateDeviceOnline();
    if (!scope.deviceOnline) {
      updateStatus('Thiết bị offline — không gửi lệnh', 'error');
      return;
    }
    if (scope.busy) { return; }
    if (confirmation && !window.confirm(confirmation)) { return; }

    scope.busy = true;
    updateStatus('Đang gửi: ' + method + ' ...', 'sending');

    var timeout = Number(self.ctx.settings.requestTimeout || 15000);
    var finished = false;
    var watchdog;

    function finishOk() {
      if (finished) { return; }
      finished = true;
      window.clearTimeout(watchdog);
      scope.busy = false;
      updateStatus('Đã gửi: ' + method, 'success');
      window.setTimeout(tgUpdateDeviceOnline, 1200);
    }

    function finishError(error) {
      if (finished) { return; }
      finished = true;
      window.clearTimeout(watchdog);
      scope.busy = false;
      var code = error && error.status ? ' (' + error.status + ')' : '';
      updateStatus('Không gửi được ' + method + code, 'error');
      window.setTimeout(tgUpdateDeviceOnline, 2500);
    }

    watchdog = window.setTimeout(function() {
      finishError({ status: 'timeout' });
    }, timeout + 1000);

    try {
      self.ctx.controlApi.sendOneWayCommand(method, params, timeout)
        .subscribe(finishOk, finishError, finishOk);
    } catch (error) {
      finishError(error);
    }
  };

  tgUpdateDeviceOnline();
  tgControlTimer = window.setInterval(tgUpdateDeviceOnline, 1000);
};

self.onDataUpdated = function() {
  tgUpdateDeviceOnline();
};

self.typeParameters = function() {
  return {
    maxDatasources: 1,
    dataKeysOptional: false,
    singleEntity: true,
    previewWidth: '760px',
    previewHeight: '360px'
  };
};

self.onDestroy = function() {
  if (tgControlTimer) {
    window.clearInterval(tgControlTimer);
    tgControlTimer = null;
  }
};
